class Solution:

    def removeAllOccurrencesOfSubstring(self, s: str, sub: str) -> str:
        n = len(s)
        i = 0
        ans = ''
        while i < n:
            j = i + len(sub)
            if j > n or s[i:j] != sub:
                ans += s[i]
                i += 1
            else:
                i = j
        return ans

