class Database:
    def __init__(self, host, port, user, password, database):
        self.host = host
        self.port = port
        self.user = user
        self.password = 
        self.database = database
        self.connection = None
        self.cursor = None

    def connect(self):
        self.connection = pymysql.connect(host=self.host, port=self.port, user=self.user, password=self.password, db=self.database)
        self.cursor = self.connection.cursor()

    def disconnect(self):
        self.cursor.close()
        self.connection.close()

    def execute(self, command):
        command_type = command[0]
        if command_type not in COMMANDTYPES:
            raise Exception('Invalid command type')
        if command_type == '*':
            self.cursor.execute(command)
            return self.cursor.fetchall()
        elif command_type == 'r':
            self.cursor.execute(command)
            return self.cursor.fetchall()
        elif command_type == 'a':
            self.cursor.execute(command)
            self.connection.commit()
            return self.cursor.lastrowid
        elif command_type == 'w':
            self.cursor.execute(command)
            self.connection.commit()
            return self.cursor.rowcount
        elif command_type == 'd':
            self.cursor.execute(command)
            self.connection.commit()
            return self.cursor.rowcount

    def get_all_tables(self):
        self.cursor.execute('SHOW TABLES')
        return self.cursor.fetchall()

    def get_all_columns(self, table_name):
        self.cursor.execute('SHOW COLUMNS FROM {}'.format(table_name))
        return self.cursor.fetchall()

    def get_all_rows(self, table_name):
        self.cursor.execute('SELECT * FROM {}'.format(table_name))
        return self.cursor.fetchall()

    def get_row_count(self, table_name):
        self.cursor.execute('SELECT COUNT(*) FROM {}'.format(table_name))
        return self.cursor.fetchone()[0]

    def get_column_count(self, table_name):
        self.cursor.execute('SELECT COUNT(*) FROM {}'.format(table_name))

