class Solution:

    def removeAllOccurrences(self, s: str, sub: str) -> str:
        ans = ''
        l = 0
        while l < len(s):
            i = s.find(sub, l)
            if i == -1:
                break
            ans += s[l:i]
            l = i + len(sub)
        ans += s[l:]
        return ans

