class Solution:

    def countDistinctSubarrays(self, nums: List[int], k: int) -> int:
        cnt = Counter()
        ans = 0
        for i in range(len(nums)):
            ans += len(cnt)
            cnt[nums[i]] += 1
            for j in range(i + 1, len(nums)):
                cnt[nums[j]] -= 1
                if cnt[nums[j]] == 0:
                    del cnt[nums[j]]
        return ans + len(cnt) // 2 * 2 + len(cnt) % 2 + 1

